using System;
using System.Collections.Immutable;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using ConsoleTables;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Controllers")]
    [TestClass]
    public class RJIT_CR_API_C_00022 : ControllerTestBase
    {
        [TestMethod]
        public void Should_Declare_SwaggerOperationId_On_Each_Http_Method()
        {
            
            var missingSwaggerOperationIds = (from controller in Controllers
                                               from method in controller.Methods
                                               where method.Attributes.Any(a => a.Name.StartWith("SwaggerOperation") &&
                                                                                a.Arguments.Any(arg => arg.Contains("OperationId"))).IsFalse()
                                               
                                               select new
                                               {
                                                   ErrorClass = controller.FullQualifiedName,
                                                   Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Controller: {controller.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
MethodName: {method.Name}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Method:     

{method.MethodValue.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:     

[SwaggerOperation(OperationId = ""{method.Name.Replace("Async", string.Empty)}"")]
{method.MethodValue.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                               }).ToImmutableList();
            

            Assert.IsTrue(missingSwaggerOperationIds.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_API_C_00022

Missing or not full filled attribute for 'SwaggerOperation'. Please check your implementation and compare it with the sample info. Findings {missingSwaggerOperationIds.Count}': {Environment.NewLine}{missingSwaggerOperationIds.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
